package com.example.shoply.domain.usecase.product

import com.example.shoply.data.repository.ProductRepository
import com.example.shoply.domain.model.Product

class InsertProductUseCase(
    private val productRepository: ProductRepository
) {
    suspend operator fun invoke(vararg products: Product) {
        if (products.isEmpty()) return
        productRepository.addProducts(products = products)
    }
}

package com.example.shoply.domain.usecase.product

import com.example.shoply.data.repository.ProductRepository
import com.example.shoply.domain.model.Product

sealed class InsertProductResult {
    object Success : InsertProductResult()
    data class Failure(val error: ProductNameValidationError) : InsertProductResult()
}

class InsertProductUseCase(
    private val productRepository: ProductRepository,
    private val validateProductNameUseCase: ValidateProductNameUseCase
) {
    suspend operator fun invoke(product: Product): InsertProductResult {
        validateProductNameUseCase(product.name)?.let { return InsertProductResult.Failure(it) }

        productRepository.addProducts(product)
        return InsertProductResult.Success
    }
}

package com.example.shoply.presentation.screens.productcatalogscreen

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.shoply.domain.model.Product
import com.example.shoply.domain.model.ProductCategory
import com.example.shoply.domain.model.ProductInList
import com.example.shoply.domain.usecase.product.DeleteProductsUseCase
import com.example.shoply.domain.usecase.product.GetProductUseCase
import com.example.shoply.domain.usecase.product.InsertProductUseCase
import com.example.shoply.domain.usecase.productinlist.AddProductsInListUseCase
import com.example.shoply.domain.usecase.productinlist.GetProductInListUseCase
import com.example.shoply.presentation.components.dialogs.UiDialog
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import java.util.UUID

class ProductCatalogScreenViewModel(
    private val getProductUseCase: GetProductUseCase,
    private val insertProductUseCase: InsertProductUseCase,
    private val addProductsInListUseCase: AddProductsInListUseCase,
    private val getProductInList: GetProductInListUseCase,
    private val deleteProductUseCase: DeleteProductsUseCase,
) : ViewModel() {
    private val _state = MutableStateFlow(State())
    val state: StateFlow<State> = _state.asStateFlow()

    data class State(
        val allProducts: List<Product> = emptyList(),
        val selectedIds: Set<UUID> = emptySet(),
        val filteredProducts: List<Product> = emptyList(),
        val productCategories: List<ProductCategory> = emptyList(),
        val searchQuery: String = "",
        val selectedCategoryFromDialog: ProductCategory = ProductCategory.ALL,
        val selectedCategoryFromFilterCategory: ProductCategory = ProductCategory.ALL,
        val existingProductCategory: Set<ProductCategory> = emptySet(),
        val activeDialog: UiDialog = UiDialog.NONE,
        val dialogInput: String = "",
        val dialogError: String? = null,
        val userMessage: String? = null,
        val isLastScreenProductListScreen: Boolean? = false,
        val transferProductList: List<ProductInList>? = emptyList()
    ) {
        val items: List<Product> =
            if (selectedCategoryFromFilterCategory == ProductCategory.ALL) {
                allProducts
            } else {
                allProducts.filter { it.category == selectedCategoryFromFilterCategory }
            }
    }

    // businnes logic
    fun addSelectedProductList(listId: UUID) {
        viewModelScope.launch(Dispatchers.IO) {

            val getAllProductsInList = getProductInList.invoke(listId = listId).first()

            _state.update { currentState ->
                currentState.copy(
                    transferProductList = getAllProductsInList
                )
            }

            val selectedProducts = _state.value.selectedIds
            val transferredProducts = _state.value.transferProductList?.map { it.product } ?: emptyList()
            val notExistingProduct =
                selectedProducts.filter { uuid -> transferredProducts.none { it.productId == uuid } }

            val productsForAdd =
                _state.value.allProducts.filter { product -> notExistingProduct.any { it == product.productId } }

            val createProductInList = productsForAdd.map {
                ProductInList(
                    productListId = listId,
                    product = it,
                )
            }

            addProductsInListUseCase.invoke(createProductInList)
        }
    }

    fun validateLastScreen(showSpecialIcon: Boolean) {
        _state.update { currentState ->
            currentState.copy(
                isLastScreenProductListScreen = showSpecialIcon
            )
        }
    }

    fun deleteProducts(){
        viewModelScope.launch(Dispatchers.IO) {
            val selectedProducts = _state.value.selectedIds
            val foundedProducts = _state.value.allProducts.filter { product -> selectedProducts.contains(product.productId) }

           deleteProductUseCase.invoke(foundedProducts)
        }
    }

    fun insertProduct(){
        viewModelScope.launch {
            val product = Product(
                name = _state.value.dialogInput,
                category = _state.value.selectedCategoryFromDialog
            )
            insertProductUseCase.invoke(product)
        }
    }


    //dialog operation
    fun onCreateDialog() {
        _state.update { currentState ->
            currentState.copy(activeDialog = UiDialog.INPUT_DIALOG)
        }
    }

    fun onDialogInputChange(input: String) {
        _state.update { currentState ->
            currentState.copy(dialogInput = input, dialogError = null)
        }
    }

    fun onSelectedProductCategory(productCategory: ProductCategory) {
        _state.update { currentState ->
            currentState.copy(selectedCategoryFromDialog = productCategory)
        }
    }

    fun dismissDialog() {
        _state.update { it.copy(activeDialog = UiDialog.NONE) }
    }

    //snackbar
    fun onMessageShown() {
        _state.update { currentState ->
            currentState.copy(
                userMessage = null
            )
        }
    }

    fun onProductCheckedChange(productId: UUID) {
        if (_state.value.selectedIds.contains(productId)) {
            _state.update { currentState ->
                currentState.copy(
                    selectedIds = currentState.selectedIds - setOf(productId)
                )
            }
            return
        }
        _state.update { currentState ->
            currentState.copy(
                selectedIds = currentState.selectedIds + setOf(productId)
            )
        }
    }

    fun addProduct(
        productName: String,
        category: ProductCategory,
        onSuccess: () -> Unit,
    ) {
        when {
            productNameIsBlank(productName) -> {}
            productNameIsTooLong(productName) -> {}
            productNameAlreadyExists(productName) -> {}
            else -> {
                val category = mapToCategory(category.name)
                insertProduct()
                _state.update { currentState ->
                    currentState.copy(
                        existingProductCategory =
                            if (!hasCategory(category.name)) currentState.existingProductCategory + category
                            else currentState.existingProductCategory,
                        userMessage = "Item added successfully"
                    )
                }
                onSuccess()
            }
        }
    }

    fun findProduct(input: String) {
        _state.update { currentState ->
            val filtered =
                if (input.isBlank()) currentState.allProducts else currentState.allProducts
                    .filter { product ->
                        product.name.contains(input, ignoreCase = true)
                    }
            currentState.copy(
                searchQuery = input,
                allProducts = filtered
            )
        }
    }

    fun onCategorySelected(item: ProductCategory) {
        _state.update { currentState ->
            currentState.copy(
                selectedCategoryFromFilterCategory = item
            )
        }
    }

    fun onDialogConfirm() {
        val error = validateProductName(_state.value.dialogInput)
        val errorText = when (error) {
            ProductNameValidationError.BLANK -> "Product name cannot be blank"
            ProductNameValidationError.TOO_LONG -> "Product name cannot be longer than 30 characters"
            ProductNameValidationError.ALREADY_EXISTS -> "Product with this name already exists"
            null -> null
        }

        if (error != null) {
            _state.update {
                it.copy(
                    dialogError = errorText
                )
            }
            return
        }
        addProduct(
            productName = _state.value.dialogInput,
            category = _state.value.selectedCategoryFromDialog,
            onSuccess = {
                dismissDialog()
            }
        )
    }

    // init
    init {
        viewModelScope.launch {
            getProductUseCase.invoke().collect {
                val existingProductCategory: Set<ProductCategory> =
                    LinkedHashSet(it.map { p -> p.category } + ProductCategory.ALL)
                _state.update { currentState ->
                    currentState.copy(
                        allProducts = it,
                        existingProductCategory = existingProductCategory,
                        productCategories = ProductCategory.entries
                    )
                }
            }
        }
    }

    // private
    private fun validateProductName(name: String): ProductNameValidationError? {
        return when {
            name.isBlank() -> ProductNameValidationError.BLANK
            name.length >= 30 -> ProductNameValidationError.TOO_LONG
            state.value.allProducts.any {
                it.name.equals(name, ignoreCase = true)
            } -> ProductNameValidationError.ALREADY_EXISTS

            else -> null
        }
    }

    private fun productNameIsBlank(productName: String) = productName.isBlank()

    private fun productNameIsTooLong(productName: String) = productName.length >= 30

    private fun productNameAlreadyExists(productName: String) =
        state.value.allProducts.any { it.name.lowercase() == productName.lowercase() }

    private fun mapToCategory(value: String): ProductCategory {
        return ProductCategory.entries.first { it.name == value }
    }

    private fun hasCategory(categoryName: String) = _state.value
        .existingProductCategory.any { it.name == categoryName }
}

enum class ProductNameValidationError {
    BLANK,
    TOO_LONG,
    ALREADY_EXISTS
}

package com.example.shoply.presentation.screens.productcatalogscreen

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.shoply.domain.model.Product
import com.example.shoply.domain.model.ProductCategory
import com.example.shoply.domain.model.ProductInList
import com.example.shoply.domain.usecase.product.DeleteProductsUseCase
import com.example.shoply.domain.usecase.product.GetProductUseCase
import com.example.shoply.domain.usecase.product.InsertProductResult
import com.example.shoply.domain.usecase.product.InsertProductUseCase
import com.example.shoply.domain.usecase.productinlist.AddProductsInListUseCase
import com.example.shoply.domain.usecase.productinlist.GetProductInListUseCase
import com.example.shoply.presentation.components.dialogs.UiDialog
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import java.util.UUID

class ProductCatalogScreenViewModel(
    private val getProductUseCase: GetProductUseCase,
    private val insertProductUseCase: InsertProductUseCase,
    private val addProductsInListUseCase: AddProductsInListUseCase,
    private val getProductInList: GetProductInListUseCase,
    private val deleteProductUseCase: DeleteProductsUseCase,
) : ViewModel() {
    private val _state = MutableStateFlow(State())
    val state: StateFlow<State> = _state.asStateFlow()

    data class State(
        val allProducts: List<Product> = emptyList(),
        val selectedIds: Set<UUID> = emptySet(),
        val filteredProducts: List<Product> = emptyList(),
        val productCategories: List<ProductCategory> = emptyList(),
        val searchQuery: String = "",
        val selectedCategoryFromDialog: ProductCategory = ProductCategory.ALL,
        val selectedCategoryFromFilterCategory: ProductCategory = ProductCategory.ALL,
        val existingProductCategory: Set<ProductCategory> = emptySet(),
        val activeDialog: UiDialog = UiDialog.NONE,
        val dialogInput: String = "",
        val dialogError: String? = null,
        val userMessage: String? = null,
        val isLastScreenProductListScreen: Boolean? = false,
        val transferProductList: List<ProductInList>? = emptyList()
    ) {
        val items: List<Product> =
            if (selectedCategoryFromFilterCategory == ProductCategory.ALL) {
                allProducts
            } else {
                allProducts.filter { it.category == selectedCategoryFromFilterCategory }
            }
    }

    // businnes logic
    fun addSelectedProductList(listId: UUID) {
        viewModelScope.launch(Dispatchers.IO) {

            val getAllProductsInList = getProductInList.invoke(listId = listId).first()

            _state.update { currentState ->
                currentState.copy(
                    transferProductList = getAllProductsInList
                )
            }

            val selectedProducts = _state.value.selectedIds
            val transferredProducts = _state.value.transferProductList?.map { it.product } ?: emptyList()
            val notExistingProduct =
                selectedProducts.filter { uuid -> transferredProducts.none { it.productId == uuid } }

            val productsForAdd =
                _state.value.allProducts.filter { product -> notExistingProduct.any { it == product.productId } }

            val createProductInList = productsForAdd.map {
                ProductInList(
                    productListId = listId,
                    product = it,
                )
            }

            addProductsInListUseCase.invoke(createProductInList)
        }
    }

    fun validateLastScreen(showSpecialIcon: Boolean) {
        _state.update { currentState ->
            currentState.copy(
                isLastScreenProductListScreen = showSpecialIcon
            )
        }
    }

    fun deleteProducts(){
        viewModelScope.launch(Dispatchers.IO) {
            val selectedProducts = _state.value.selectedIds
            val foundedProducts = _state.value.allProducts.filter { product -> selectedProducts.contains(product.productId) }

           deleteProductUseCase.invoke(foundedProducts)
        }
    }

    // ...existing code... (removed standalone insertProduct; insertion is handled from addProduct and awaits result)


    //dialog operation
    fun onCreateDialog() {
        _state.update { currentState ->
            currentState.copy(activeDialog = UiDialog.INPUT_DIALOG)
        }
    }

    fun onDialogInputChange(input: String) {
        _state.update { currentState ->
            currentState.copy(dialogInput = input, dialogError = null)
        }
    }

    fun onSelectedProductCategory(productCategory: ProductCategory) {
        _state.update { currentState ->
            currentState.copy(selectedCategoryFromDialog = productCategory)
        }
    }

    fun dismissDialog() {
        _state.update { it.copy(activeDialog = UiDialog.NONE) }
    }

    //snackbar
    fun onMessageShown() {
        _state.update { currentState ->
            currentState.copy(
                userMessage = null
            )
        }
    }

    fun onProductCheckedChange(productId: UUID) {
        if (_state.value.selectedIds.contains(productId)) {
            _state.update { currentState ->
                currentState.copy(
                    selectedIds = currentState.selectedIds - setOf(productId)
                )
            }
            return
        }
        _state.update { currentState ->
            currentState.copy(
                selectedIds = currentState.selectedIds + setOf(productId)
            )
        }
    }

    fun addProduct(
        productName: String,
        category: ProductCategory,
        onSuccess: () -> Unit,
    ) {
        // quick synchronous checks for immediate UX
        if (productNameIsBlank(productName)) {
            _state.update { it.copy(dialogError = "Product name cannot be blank") }
            return
        }
        if (productNameIsTooLong(productName)) {
            _state.update { it.copy(dialogError = "Product name cannot be longer than 30 characters") }
            return
        }

        viewModelScope.launch {
            val product = Product(
                name = productName,
                category = category
            )

            val result = insertProductUseCase.invoke(product)

            when (result) {
                is InsertProductResult.Success -> {
                    val mappedCategory = mapToCategory(category.name)
                    _state.update { currentState ->
                        currentState.copy(
                            existingProductCategory =
                                if (!hasCategory(mappedCategory.name)) currentState.existingProductCategory + mappedCategory
                                else currentState.existingProductCategory,
                            userMessage = "Item added successfully"
                        )
                    }
                    onSuccess()
                }
                is InsertProductResult.Failure -> {
                    val errorText = when (result.error) {
                        ProductNameValidationError.BLANK -> "Product name cannot be blank"
                        ProductNameValidationError.TOO_LONG -> "Product name cannot be longer than 30 characters"
                        ProductNameValidationError.ALREADY_EXISTS -> "Product with this name already exists"
                    }
                    _state.update { it.copy(dialogError = errorText) }
                }
            }
        }
    }

    fun findProduct(input: String) {
        _state.update { currentState ->
            val filtered =
                if (input.isBlank()) currentState.allProducts else currentState.allProducts
                    .filter { product ->
                        product.name.contains(input, ignoreCase = true)
                    }
            currentState.copy(
                searchQuery = input,
                allProducts = filtered
            )
        }
    }

    fun onCategorySelected(item: ProductCategory) {
        _state.update { currentState ->
            currentState.copy(
                selectedCategoryFromFilterCategory = item
            )
        }
    }

    fun onDialogConfirm() {
        val error = validateProductName(_state.value.dialogInput)
        val errorText = when (error) {
            ProductNameValidationError.BLANK -> "Product name cannot be blank"
            ProductNameValidationError.TOO_LONG -> "Product name cannot be longer than 30 characters"
            ProductNameValidationError.ALREADY_EXISTS -> "Product with this name already exists"
            null -> null
        }

        if (error != null) {
            _state.update {
                it.copy(
                    dialogError = errorText
                )
            }
            return
        }
        addProduct(
            productName = _state.value.dialogInput,
            category = _state.value.selectedCategoryFromDialog,
            onSuccess = {
                dismissDialog()
            }
        )
    }

    // init
    init {
        viewModelScope.launch {
            getProductUseCase.invoke().collect {
                val existingProductCategory: Set<ProductCategory> =
                    LinkedHashSet(it.map { p -> p.category } + ProductCategory.ALL)
                _state.update { currentState ->
                    currentState.copy(
                        allProducts = it,
                        existingProductCategory = existingProductCategory,
                        productCategories = ProductCategory.entries
                    )
                }
            }
        }
    }

    // private
    private fun validateProductName(name: String): ProductNameValidationError? {
        return when {
            name.isBlank() -> ProductNameValidationError.BLANK
            name.length >= 30 -> ProductNameValidationError.TOO_LONG
            state.value.allProducts.any {
                it.name.equals(name, ignoreCase = true)
            } -> ProductNameValidationError.ALREADY_EXISTS

            else -> null
        }
    }

    private fun productNameIsBlank(productName: String) = productName.isBlank()

    private fun productNameIsTooLong(productName: String) = productName.length >= 30

    private fun productNameAlreadyExists(productName: String) =
        state.value.allProducts.any { it.name.lowercase() == productName.lowercase() }

    private fun mapToCategory(value: String): ProductCategory {
        return ProductCategory.entries.first { it.name == value }
    }

    private fun hasCategory(categoryName: String) = _state.value
        .existingProductCategory.any { it.name == categoryName }
}

enum class ProductNameValidationError {
    BLANK,
    TOO_LONG,
    ALREADY_EXISTS
}
